<map version="1.0.1"><node CREATED="1747229343780" ID="ID_root" MODIFIED="1747229343780" TEXT="Day08_字符串"><node CREATED="1747229343780" ID="ID_043e5f55a5537b04" POSITION="right" MODIFIED="1747229343780" TEXT="什么是字符串"><node CREATED="1747229343780" ID="ID_3b7d6f779b370772" MODIFIED="1747229343780" TEXT="在C中，字符串，就是一个特殊的字符数组。&amp;nbsp;&amp;lt;br&amp;gt;以 \0结尾。&amp;nbsp;"></node><node CREATED="1747229343780" ID="ID_ef7095a6494bb9fe" MODIFIED="1747229343780" TEXT="C里面的字符串设计不是特别好。&amp;lt;br&amp;gt;问题1：&amp;nbsp;字符串本身无法存储 \0&amp;nbsp;&amp;nbsp;&amp;lt;br&amp;gt;问题2：&amp;nbsp;每一次看字符串的长度，都要遍历一遍字符数组"><node CREATED="1747229343780" ID="ID_39822a09d0b98939" MODIFIED="1747229343780" TEXT="在后期的编程语言设计中，基本都会采用&amp;lt;br&amp;gt;字符数组+额外信息来&amp;nbsp;整体表示一个字符串。&amp;nbsp;&amp;lt;br&amp;gt;比如C++,&amp;nbsp;比如Java。&amp;nbsp;"></node></node></node><node CREATED="1747229343780" ID="ID_6696ef000bddebad" POSITION="right" MODIFIED="1747229343780" TEXT="字符串字面值"><node CREATED="1747229343780" ID="ID_df578e245057a73a" MODIFIED="1747229343780" TEXT="我们平时使用的双引号引起来的，就是字符串字面值"></node><node CREATED="1747229343780" ID="ID_b8236ad212847dc6" MODIFIED="1747229343780" TEXT="写法"><node CREATED="1747229343780" ID="ID_f9e9c55ac4920b2b" MODIFIED="1747229343780" TEXT="第一种写法一定要知道。&amp;nbsp;&amp;lt;br&amp;gt;&amp;quot;hello world&amp;quot;"></node></node><node CREATED="1747229343780" ID="ID_f484d8bf758ced8f" MODIFIED="1747229343780" TEXT="存储位置"><node CREATED="1747229343780" ID="ID_754dc712a09cf926" MODIFIED="1747229343780" TEXT="存储一个叫做只读数据段上的区域。&amp;nbsp;特点就是&amp;lt;br&amp;gt;只读&amp;lt;br&amp;gt;生命周期静态生命周期（活的够久）"></node><node CREATED="1747229343780" ID="ID_cecebe4cb32e99f7" MODIFIED="1747229343780" TEXT="还是以&amp;nbsp;字符数组的形式存的。以 \0结尾的"></node></node><node CREATED="1747229343780" ID="ID_ffc51783458bdd80" MODIFIED="1747229343780" TEXT="字符串字面值的操作"><node CREATED="1747229343780" ID="ID_81d3dfe29e95138b" MODIFIED="1747229343780" TEXT="一般是在printf的时候传入。这时候，字符串字面值其实退化成了首指针。&amp;lt;br&amp;gt;它怎么知道这个数组多长？&amp;lt;br&amp;gt;直接是往后找，找到 \0&amp;nbsp;认为终止"></node><node CREATED="1747229343780" ID="ID_5b0d82bdc5bdec41" MODIFIED="1747229343780" TEXT="使用指针接收"><node CREATED="1747229343780" ID="ID_f1983ddc5b9191ae" MODIFIED="1747229343780" TEXT="char *p = &amp;quot;hello&amp;quot;;"></node><node CREATED="1747229343780" ID="ID_4d4c2c88a540eb89" MODIFIED="1747229343780" TEXT="但是需要注意的点是：&amp;nbsp;使用指针接收，指针指向的内存是只读数据段上的区域。&amp;lt;br&amp;gt;换句话说，就是我们不能通过这个指针去修改这个数据。"></node></node></node></node><node CREATED="1747229343780" ID="ID_7bcf64cd5b25fe79" POSITION="right" MODIFIED="1747229343780" TEXT="字符串变量"><node CREATED="1747229343780" ID="ID_7d84a64c5e46221d" MODIFIED="1747229343780" TEXT="声明"><node CREATED="1747229343780" ID="ID_c47959dffa5d1b70" MODIFIED="1747229343780" TEXT="因为C中的字符串，就是字符数组。所以声明字符串，就是声明字符数组。&amp;nbsp;&amp;lt;br&amp;gt;区别就是我们声明的字符数组，应该注意一下 +1就行。&amp;nbsp;&amp;lt;br&amp;gt;比如，现在要存储长度最多80的字符串，声明字符数组长度应该 80+1"></node><node CREATED="1747229343780" ID="ID_42b9e0b8c907440f" MODIFIED="1747229343780" TEXT="char str[80+1];&amp;lt;br&amp;gt;char *str2;&amp;lt;br&amp;gt;//&amp;nbsp;后面这种声明需要注意一下。&amp;nbsp;这个指针不能直接用，需要指向有效的内存"></node></node><node CREATED="1747229343780" ID="ID_f67dc001138ae66b" MODIFIED="1747229343780" TEXT="初始化"><node CREATED="1747229343780" ID="ID_3b36c09e79afab76" MODIFIED="1747229343780" TEXT="char str[] = &amp;quot;hello&amp;quot;;&amp;lt;br&amp;gt;// 上述代码等价于&amp;lt;br&amp;gt;char str2[] = {&amp;apos;h&amp;apos;, &amp;apos;e&amp;apos;, &amp;apos;l&amp;apos;, &amp;apos;l&amp;apos;, &amp;apos;o&amp;apos;, &amp;apos;\0&amp;apos;};&amp;lt;br&amp;gt;这是一种语法糖，只是一个简写形式"></node><node CREATED="1747229343780" ID="ID_13d8a43bbadbe617" MODIFIED="1747229343780" TEXT="其他的初始化形式都比较简单。&amp;nbsp;&amp;lt;br&amp;gt;要注意给 \0&amp;nbsp;留个位置就可以了&amp;lt;br&amp;gt;"></node><node CREATED="1747229343780" ID="ID_9581b0cc562dffb4" MODIFIED="1747229343780" TEXT="char str[] = &amp;quot;Showmaker&amp;quot;;&amp;lt;br&amp;gt;char *p = &amp;quot;Showmaker&amp;quot;;&amp;lt;br&amp;gt;这两种写法有这本质的区别"><node CREATED="1747229343780" ID="ID_70ec9dade9e5bcd3" MODIFIED="1747229343780" TEXT="第一种写法是个语法糖，会在栈上申请内存。换句话说，它里面的数据可以修改"></node><node CREATED="1747229343780" ID="ID_f002592b826036ec" MODIFIED="1747229343780" TEXT="第二种是一个指针，指针指向只读数据段。所以，指针指向的这片内存无法修改，一修改就报错"></node></node></node><node CREATED="1747229343780" ID="ID_660a15bc85f31845" MODIFIED="1747229343780" TEXT="字符串的输出和输入"><node CREATED="1747229343780" ID="ID_e66a0d11b3c48e86" MODIFIED="1747229343780" TEXT="遍历/往屏幕输出"><node CREATED="1747229343780" ID="ID_7420b0957bb1c247" MODIFIED="1747229343780" TEXT="char str[] = &amp;quot;hello world!&amp;quot;;&amp;lt;br&amp;gt;for (int i = 0; str[i] != &amp;apos;\0&amp;apos;; i++) {&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; printf(&amp;quot;%c\n&amp;quot;, str[i]);&amp;lt;br&amp;gt;}&amp;lt;br&amp;gt;"><node CREATED="1747229343780" ID="ID_0ef3f6faa77a8e68" MODIFIED="1747229343780" TEXT="建议使用 while循环。&amp;nbsp;for可以"></node></node><node CREATED="1747229343780" ID="ID_a00a6bfd7b8ace73" MODIFIED="1747229343780" TEXT="char* p = str;&amp;lt;br&amp;gt;while (*p != &amp;apos;\0&amp;apos;) {&amp;nbsp; &amp;nbsp; // 等价于 *p != 0，即字符不是空字符就继续遍历&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; printf(&amp;quot;%c\n&amp;quot;, *p++);&amp;lt;br&amp;gt;}"></node><node CREATED="1747229343780" ID="ID_10f6c73a81d52e74" MODIFIED="1747229343780" TEXT="printf(&amp;quot;%s\n&amp;quot;, str);&amp;lt;br&amp;gt;puts(str);"></node><node CREATED="1747229343780" ID="ID_c287c92ded569cff" MODIFIED="1747229343780" TEXT="推荐使用while循环。且一定要会&amp;lt;br&amp;gt;因为遍历操作很常见"><node CREATED="1747229343780" ID="ID_f4906b71514e5710" MODIFIED="1747229343780" TEXT="需要注意，要么挪指针，要么直接偏移&amp;lt;br&amp;gt;不要一边挪指针，一边偏移"></node></node></node><node CREATED="1747229343780" ID="ID_af8a66051069547c" MODIFIED="1747229343780" TEXT="输入"><node CREATED="1747229343780" ID="ID_531a621b7486ed52" MODIFIED="1747229343780" TEXT="scanf(&amp;quot;%s&amp;quot;, arr);&amp;lt;br&amp;gt;输入一个字符串，存储到arr。&amp;lt;br&amp;gt;"><node CREATED="1747229343780" ID="ID_6ddaf5f038723f9d" MODIFIED="1747229343780" TEXT="不安全，也就是录入的字符串太长了。&amp;lt;br&amp;gt;会全部录进来"></node><node CREATED="1747229343780" ID="ID_b307f26c96996d0d" MODIFIED="1747229343780" TEXT="scanf(&amp;quot;%9s&amp;quot;,arr);&amp;lt;br&amp;gt;最多存储9个，第10个存零字符"></node></node></node></node></node><node CREATED="1747229343780" ID="ID_82b676184d452b87" POSITION="right" MODIFIED="1747229343780" TEXT="字符串库"><node CREATED="1747229343780" ID="ID_f15f875ae40020d4" MODIFIED="1747229343780" TEXT="C里面的字符串是字符数组存储的，有一些操作是普遍的，&amp;lt;br&amp;gt;比如求字符串长度，比如比较两个字符串是否相等。&amp;lt;br&amp;gt;字符串库简单说就是一系列函数，帮助我们更方便的操作字符串"></node><node CREATED="1747229343780" ID="ID_5e776b68e9cea8dc" MODIFIED="1747229343780" TEXT="strlen"><node CREATED="1747229343780" ID="ID_764ed5abc8ab9ea9" MODIFIED="1747229343780" TEXT="计算字符串长度"></node><node CREATED="1747229343780" ID="ID_f71dbd4d4015fa2c" MODIFIED="1747229343780" TEXT="size_t strlen(const char *s);"></node><node CREATED="1747229343780" ID="ID_62c561663a5a4719" MODIFIED="1747229343780" TEXT="传入的地址应该是一个字符串（以空字符结尾），否则会产生越界访问，未定义行为。&amp;nbsp;"></node><node CREATED="1747229343780" ID="ID_a6ae1dda834793af" MODIFIED="1747229343780" TEXT="sizeof和strlen区别要知道"><node CREATED="1747229343780" ID="ID_a4dfe227d2baedb4" MODIFIED="1747229343780" TEXT="char str[10] = &amp;quot;hello&amp;quot;;"></node><node CREATED="1747229343780" ID="ID_70db53fa34d7a5ed" MODIFIED="1747229343780" TEXT="sizeof用于计算某个位置占用多少大小。比如传数组，得到的是数组占用的大小空间。"></node><node CREATED="1747229343780" ID="ID_96ba798022f7cb93" MODIFIED="1747229343780" TEXT="strlen用于计算一个字符串长度，计算的是从头到空字符的长度。"></node><node CREATED="1747229343780" ID="ID_245a5263bd7d3e30" MODIFIED="1747229343780" TEXT="面试一般问：&amp;nbsp;难点、易混淆的点"></node></node><node CREATED="1747229343780" ID="ID_242d0e72d9ba9ff4" MODIFIED="1747229343780" TEXT="要自己能实现strlen"><node CREATED="1747229343780" ID="ID_8de1f1275c0f5c10" MODIFIED="1747229343780" TEXT="如果一种写法没有明显的好处，但是又有明显的坏处。&amp;lt;br&amp;gt;不太建议"></node></node></node><node CREATED="1747229343780" ID="ID_44704ad5f60ea1bc" MODIFIED="1747229343780" TEXT="strcpy"><node CREATED="1747229343780" ID="ID_34976cb44469d2a7" MODIFIED="1747229343780" TEXT="完成字符串的复制"></node><node CREATED="1747229343780" ID="ID_92385ecad7169b11" MODIFIED="1747229343780" TEXT="这个是直接就是复制，不关心能否存下"></node><node CREATED="1747229343780" ID="ID_ace45fb388daa693" MODIFIED="1747229343780" TEXT="strncpy:&amp;nbsp;是一个更安全的字符串复制函数"><node CREATED="1747229343780" ID="ID_684cf3f1a575d943" MODIFIED="1747229343780" TEXT="最多复制n个字符"></node><node CREATED="1747229343780" ID="ID_0230edc2ee7c4921" MODIFIED="1747229343780" TEXT="如果n比较小，比 strlen(src) +1&amp;nbsp;小。只复制n个"></node><node CREATED="1747229343780" ID="ID_c5c8cf9d783e3b71" MODIFIED="1747229343780" TEXT="如果n比较巧，刚好等于 strlen(src) + 1。 也复制n个"></node><node CREATED="1747229343780" ID="ID_c2b28583f527d358" MODIFIED="1747229343780" TEXT="如果n比较大，比&amp;nbsp; strlen(src) + 1,&amp;nbsp; 前面的数据拷贝过来，后面填 &amp;apos;\0&amp;apos;"></node><node CREATED="1747229343780" ID="ID_cd755ca0354b9151" MODIFIED="1747229343780" TEXT="n的建议： sizeof(dest)-1&amp;lt;br&amp;gt;dest[sizeof(dest)-1] = &amp;apos;\0&amp;apos;&amp;nbsp;"></node></node></node><node CREATED="1747229343780" ID="ID_4f1fa1f28f185608" MODIFIED="1747229343780" TEXT="strcat"><node CREATED="1747229343780" ID="ID_a734a341848b1815" MODIFIED="1747229343780" TEXT="完成字符串的拼接"></node><node CREATED="1747229343780" ID="ID_e9f368c7d64ec944" MODIFIED="1747229343780" TEXT="将src表示的字符串，拼接到dest的后面。&amp;lt;br&amp;gt;也就是从dest的 \0位置开始覆盖。直到结束"></node><node CREATED="1747229343780" ID="ID_3ebcc4d444fe5011" MODIFIED="1747229343780" TEXT="strncat:&amp;nbsp;更安全的cat函数&amp;lt;br&amp;gt;concat:&amp;nbsp;拼接"><node CREATED="1747229343780" ID="ID_21cd963b67a84254" MODIFIED="1747229343780" TEXT="有两种情况会终止：要么复制到了n个字符"></node><node CREATED="1747229343780" ID="ID_d5e59423b64e2ce5" MODIFIED="1747229343780" TEXT="要么复制到了src的末尾"></node><node CREATED="1747229343780" ID="ID_e720c9d2a360e88d" MODIFIED="1747229343780" TEXT="最终一定会补一个 \0"></node><node CREATED="1747229343780" ID="ID_9d6356716923ceea" MODIFIED="1747229343780" TEXT="建议的n: sizeof(dest) - strlen(dest) -1"></node></node></node><node CREATED="1747229343780" ID="ID_856f25eced4d77b4" MODIFIED="1747229343780" TEXT="strcmp"><node CREATED="1747229343780" ID="ID_2574d886fa56ccf2" MODIFIED="1747229343780" TEXT="compare:&amp;nbsp;就是比较两个字符串是否相等。&amp;nbsp;&amp;lt;br&amp;gt;"></node><node CREATED="1747229343780" ID="ID_df8f645894302160" MODIFIED="1747229343780" TEXT="字符串怎么叫相等"><node CREATED="1747229343780" ID="ID_dfa3f3ac491a8303" MODIFIED="1747229343780" TEXT="字典序"></node></node></node></node><node CREATED="1747229343780" ID="ID_e96a32f6b8484ab2" POSITION="right" MODIFIED="1747229343780" TEXT="字符串数组"><node CREATED="1747229343780" ID="ID_2b46cfd80085c9d4" MODIFIED="1747229343780" TEXT="研究的是有一组字符串如何存储的问题"></node><node CREATED="1747229343780" ID="ID_12c9cf095729cbfd" MODIFIED="1747229343780" TEXT="两种存储方式"><node CREATED="1747229343780" ID="ID_8546af3198591c63" MODIFIED="1747229343780" TEXT="二维字符数组"><node CREATED="1747229343780" ID="ID_3141b86122aa2788" MODIFIED="1747229343780" TEXT="了解一下就行"></node><node CREATED="1747229343780" ID="ID_59b63c8f691e1a3e" MODIFIED="1747229343780" TEXT="如果有一个字符串太长，则其他的都要这么长。换句话说，有大量空间浪费"></node></node><node CREATED="1747229343780" ID="ID_5c8d99a6381ecc0a" MODIFIED="1747229343780" TEXT="指针数组&amp;lt;br&amp;gt;"><node CREATED="1747229343780" ID="ID_3726763332b7074c" MODIFIED="1747229343780" TEXT="单个字符串是字符数组，我们可以用一个指针指向它。==》单个字符串可以用指针表示。&amp;lt;br&amp;gt;一组字符串，可以使用指针数组（是数组，数组里每个元素都是指针）。来存储"></node></node></node></node><node CREATED="1747229343780" ID="ID_7a31dbe5bb70ef20" POSITION="right" MODIFIED="1747229343780" TEXT="命令行参数"><node CREATED="1747229343781" ID="ID_832819c414cdfd30" MODIFIED="1747229343781" TEXT="字符串数组的一个实际案例。"></node><node CREATED="1747229343781" ID="ID_46525c5b70daded4" MODIFIED="1747229343781" TEXT="有时候，是允许你运行时给一些参数的。在程序内部，需要接收这个参数，这时候就是使用的字符串数组"></node><node CREATED="1747229343781" ID="ID_e080add2f14de873" MODIFIED="1747229343781" TEXT="关于这块，知道两件事"><node CREATED="1747229343781" ID="ID_6ed1f28aab9b2a3f" MODIFIED="1747229343781" TEXT="系统会将你给的输入，处理好，处理成指针数组，并且将数据给你。"></node><node CREATED="1747229343781" ID="ID_d67f76d7f6468dbe" MODIFIED="1747229343781" TEXT="我们需要知道接收的格式。&amp;nbsp;就是第一个参数是什么含义，第二个参数是什么含义即可"></node></node></node><node CREATED="1747229343781" ID="ID_5019dfdc3a481f80" POSITION="right" MODIFIED="1747229343781" TEXT="结构体"><node CREATED="1747229343781" ID="ID_1b906e00fa2a52cc" MODIFIED="1747229343781" TEXT="就是将一些数据放在一个类型中。让这个一个类型能存放多个数据"></node><node CREATED="1747229343781" ID="ID_fd0712d7854d7045" MODIFIED="1747229343781" TEXT="结构体的定义"><node CREATED="1747229343781" ID="ID_c1b9b15afe028b9f" MODIFIED="1747229343781" TEXT="定义一个类型。这个类型就类似于int"></node></node><node CREATED="1747229343781" ID="ID_a30835f2ec16e60c" MODIFIED="1747229343781" TEXT="声明结构体"><node CREATED="1747229343781" ID="ID_3250641825d6807d" MODIFIED="1747229343781" TEXT="struct&amp;nbsp;结构体名&amp;nbsp;结构体变量名;&amp;lt;br&amp;gt;int&amp;nbsp; num; //&amp;nbsp;类似。&amp;nbsp;只是要写struct"></node><node CREATED="1747229343781" ID="ID_48c02d90f18bd17f" MODIFIED="1747229343781" TEXT="如果想不加struct。&amp;nbsp;要用类型别名。&amp;nbsp;名称区分一下。&amp;nbsp;使用大驼峰"></node></node><node CREATED="1747229343781" ID="ID_7a77e3cf1c7ef214" MODIFIED="1747229343781" TEXT="初始结构体"><node CREATED="1747229343781" ID="ID_8c7f3de6c2d77289" MODIFIED="1747229343781" TEXT="给结构体对象中的值赋值。"></node><node CREATED="1747229343781" ID="ID_b48c972befabef39" MODIFIED="1747229343781" TEXT="如果全部赋值，挨个赋进去&amp;lt;br&amp;gt;如果赋了部分，&amp;nbsp;后面就是0值"></node></node><node CREATED="1747229343781" ID="ID_2cbc888f04992d1a" MODIFIED="1747229343781" TEXT="数据对齐"><node CREATED="1747229343781" ID="ID_2f5f9814ae08356a" MODIFIED="1747229343781" TEXT="为了保证访问数据的高效，结构体这块存在一个对齐。&amp;nbsp;简单说，就是凑4字节的整数。&amp;lt;br&amp;gt;怎么凑，不重要；&amp;nbsp;重要的是要知道有这个对齐；&amp;lt;br&amp;gt;后续计算结构体大小，使用sizeof()&amp;nbsp;不要自己加"></node></node></node><node CREATED="1747229343781" ID="ID_a91890e42980510b" POSITION="right" MODIFIED="1747229343781" TEXT="枚举"></node></node></map>